'use strict';
// Extracted enhance RPC handlers (enhance/progress, enhance, cancel) from legacy host source.
// build-host.mjs injects this chunk back into the generated host bundle.
// M2 深化：enhance 主流程已管道化（bundle 内 Pipeline，四 stage 注册）。
module.exports = "    // ================= M2 深化：增强管道（bundle 内 Pipeline，契约同已退役的 M2 骨架（P1b 2026-09-19））=================\n    // 新增增强模式 / 检索源 = registerEnhanceStage 注册 stage handler，而非修改 enhance 主流程。\n    // 2026-08-18（模板体系修订）：每模式 2 个内置模板（default/increment）+ 多自定义模板——\n    // system 组装改走 pure.js resolveTemplateSystem（pick/custom 解析 + 旧配置兼容迁移）。\n    const enhancePipelineHandlers = new Map();\n    function registerEnhanceStage(name, handler, options) {\n      const priority = options && Number.isInteger(options.priority) ? options.priority : 0;\n      const list = enhancePipelineHandlers.get(name) || [];\n      list.push({ handler, priority });\n      list.sort((a, b) => a.priority - b.priority);\n      enhancePipelineHandlers.set(name, list);\n    }\n    async function runEnhanceStages(name, value) {\n      const list = enhancePipelineHandlers.get(name) || [];\n      let v = value;\n      for (const { handler } of list) {\n        v = await handler(v);\n      }\n      return v;\n    }\n\n    // v2.3（§7.3）：优化进度轮询 RPC——从 pending Map 读 stage（纯展示，失败静默降级）\n    harness.handle('enhance/progress', async (args) => {\n      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : '';\n      const seq = args && typeof args.seq === 'number' ? args.seq : -1;\n      const rec = pending.get(requestKey(sessionId, seq));\n      if (!rec) return { ok: false, code: 'NO_RECORD' };\n      // v3.0r（细粒度进度反馈）：返回 stage + 子步骤详情 + 已用时间（纯展示，失败静默降级）\n      return {\n        ok: true,\n        stage: rec.stage || STAGE_PREPARE,\n        detailKey: rec.detailKey || '',\n        detailArgs: rec.detailArgs || null,\n        step: rec.step || 0,\r\n        total: rec.total || 0,\r\n        elapsedMs: rec.startedAt ? Date.now() - rec.startedAt : 0,\r\n        // P0-d：降级清单（辅助调用失败 → 结果在「半瞎」状态生成，用户须可见）\r\n        degraded: Array.isArray(rec.degraded) ? rec.degraded.slice() : [],\r\n        // 复审 medium ⑦ 的配套：重试与降级分通道——重试次数单独暴露（可观测），\r\n        // 混进 degraded 会把「重试后成功」误标成「部分上下文不可用」。\r\n        retries: Array.isArray(rec.retries) ? rec.retries.slice() : [],\r\n      };\n    });\n\n    // P0-d（2026-10-12 · 让降级可见）：辅助调用失败此前只写 hlog（环形日志），用户侧零痕迹 ⇒\r\n    // 用户不知道增强结果是在「半瞎」状态下生成的。此处把每次降级登记到 rec.degraded（去重、可枚举），\r\n    // 经 enhance/progress 暴露给 UI，并随最终 result 一并回传（结果态可见）。\r\n    function markDegraded(state, kind) {\r\n      if (!state || !state.rec) return;\r\n      const rec = state.rec;\r\n      if (!Array.isArray(rec.degraded)) rec.degraded = [];\r\n      const k = String(kind || 'unknown');\r\n      if (rec.degraded.indexOf(k) === -1) rec.degraded.push(k);\r\n    }\r\n\r\n    // P0-a（2026-10-12 · 补退避重试）：取官方**已解析**的重试策略——按主机文要求**不得硬编码**退避参数，\r\n    // 必须调 ctx.llm.providerRetryPolicy(provider) 取官方解析好的策略再执行（可重试码集同样从策略取）。\r\n    // 旧宿主/未注册路由/服务缺该 API → 返回 null（调用方不重试，行为回到「只尝试一次」）。\r\n    function retryPolicyFor(provider) {\r\n      if (llm === undefined || typeof llm.providerRetryPolicy !== 'function') return null;\r\n      try {\r\n        const pol = llm.providerRetryPolicy(provider);\r\n        return pol && typeof pol === 'object' ? pol : null;\r\n      } catch (e) {\r\n        hlog('[enhance] providerRetryPolicy failed provider=' + provider + ' ' + (e && e.message ? e.message : e));\r\n        return null;\r\n      }\r\n    }\r\n\r\n    // P0-a：`always` 模式下官方策略无 maxRetries（不设限）——插件侧安全上限，防无限制组合下不收敛。\r\n    const RETRY_ALWAYS_SAFETY_CAP = 5;\r\n\r\n    // P0-a：可中断退避睡眠（经 ctx.timer，宿主销毁即随 fiber 释放；不用裸 setTimeout）。\r\n    // 0/负延迟 → 立即返回；timer 服务异常 → 退化为不等待（重试仍会进行，不会挂死）。\r\n    async function sleepMs(ms) {\r\n      const d = Number(ms);\r\n      if (!Number.isFinite(d) || d <= 0) return;\r\n      try {\r\n        // ctx.timer.timeout(callback, delay)：回调式 API（disposer 返回），包成 Promise 等待一次。\r\n        await new Promise((resolve) => {\r\n          try {\r\n            ctx.timer.timeout(() => resolve(), d);\r\n          } catch (e) { resolve(); }\r\n        });\r\n      } catch (e) { /* 上下文销毁 → 直接继续（由 rec.cancelled/timedOut 兜底） */ }\r\n    }\r\n\r\n    // P0-b（2026-10-12 · 辅助调用并入同一预算）：返回距主预算还余多少毫秒；未设预算 → Infinity。\r\n    // 调用点据此把各辅助调用自己的 10–15s 超时**钳到剩余预算内**，并使预算耗尽时直接跳过\r\n    // （记录降级，不阻断主流程）——准备阶段由此纳入主预算，而非各自为政。\r\n    function remainingBudgetMs(state) {\r\n      const dl = state && typeof state.budgetDeadline === 'number' ? state.budgetDeadline : null;\r\n      if (dl === null) return Infinity;\r\n      return Math.max(0, dl - Date.now());\r\n    }\r\n    function helperTimeoutMs(state, baseMs) {\r\n      const remain = remainingBudgetMs(state);\r\n      if (remain === Infinity) return baseMs;\r\n      return Math.max(0, Math.min(baseMs, remain));\r\n    }\r\n    // 预算是否已耗尽（辅助调用直接跳过 + 记降级）\r\n    function budgetExhausted(state) {\r\n      return remainingBudgetMs(state) <= 0;\r\n    }\r\n\r\n    // P0-b 修正（2026-10-12 · 独立复核 blocker）：辅助调用超时必须**真正中断其流**。\r\n    // 原实现只把 timedOut 置 true，而 `await collectStream(iterator, …)` 会一直等到流自己结束\r\n    // ⇒ 慢但健康的辅助会跑过自己的钳后超时（实测 20s 钳制下仍跑到 23–24s），\r\n    // 从而越过 prepareBudgetMs 侵蚀 genTimeoutMs —— 复现实测：辅助 23s/24s 时生成 genCalls=0、\r\n    // 整体 TIMEOUT（HEAD 同场景 ok:true）——正是 P0-b 自述要防的「拆东墙」。\r\n    // 现改为：超时到点即 `iterator.return()` 中止流 + **立即以超时结算**（绝不等待流自然结束）。\r\n    // 实现为一个可 race 的「超时闸」：闸开 → 中止迭代器 + 以 {kind:'aborted'} 结算。\r\n    // 返回 { timedOut(), attach(iterator), race(collectPromise), dispose() }。\r\n    function startHelperAbort(state, baseMs) {\r\n      const ms = helperTimeoutMs(state, baseMs);\r\n      let fired = false;\r\n      let iterator = null;\r\n      let fireTimer = null;\r\n      let settle = null;\r\n      const abortIterator = () => {\r\n        // 真中断：迭代器 return()（官方 AsyncIterable 契约）——底层适配器随即停止产出\r\n        if (iterator && typeof iterator.return === 'function') {\r\n          try { iterator.return(); } catch (e) { /* 忽略 */ }\r\n        }\r\n      };\r\n      // 超时闸：到点 → 置标志 + 中止流 + 让 race 以 aborted 结算（不再等流自然结束）\r\n      const gate = new Promise((resolve) => { settle = resolve; });\r\n      if (ms > 0) {\r\n        fireTimer = ctx.timer.timeout(() => {\r\n          fired = true;\r\n          abortIterator();\r\n          try { settle({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }\r\n        }, ms);\r\n      } else {\r\n        // 预算已耗尽 → 立即超时（调用点会据此跳过并记降级）\r\n        fired = true;\r\n        try { settle({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }\r\n      }\r\n      return {\r\n        timedOut: () => fired,\r\n        attach: (it) => { iterator = it; if (fired) abortIterator(); },\r\n        race: (collectPromise) => Promise.race([collectPromise, gate]),\r\n        dispose: () => { try { if (fireTimer) fireTimer(); } catch (e) { /* 忽略 */ } abortIterator(); },\r\n      };\r\n    }\r\n\r\n    // v3.0r（细粒度进度反馈）：写进度详情（stage/detailKey/detailArgs/step/total）\r\n    function setProgress(rec, stage, key, args, step, total) {\n      rec.stage = stage;\n      rec.detailKey = key || '';\n      rec.detailArgs = args || null;\n      rec.step = step || 0;\n      rec.total = total || 0;\n    }\n\n    // ---- stage: analyze——配置解析 / 模型链 / system 组装 / 记忆与场景准备 ----\n    async function enhanceStageAnalyze(state) {\n      const args = state.args;\n      const sessionId = state.sessionId;\n      const text = state.text;\n      // 2026-08-18（用户需求·每模式步骤补充）：analyze 阶段开始即上报进度「分析任务」\n      if (state.rec) setProgress(state.rec, STAGE_ANALYZE);\n      const cfg = validateConfig(args && args.config);\n      // v2.1（§2.2）：client 已判定实际模式（显式/auto/seed），请求 mode 覆盖解析值\n      if (args && typeof args.mode === 'string' && MODE_KEYS.includes(args.mode)) cfg.mode = args.mode;\n      // v2.8.2 曾一键发布记忆强制开启；2026-08-18（用户指令）取消——记忆跟随开关，publish 不例外\n      // v23（D6）：模型链 = cfg.fallback 按序（每条独立 reasoningEffort）；\n      // 2026-08-18（用户需求·删内置兜底链）：完全按用户配置顺序——链为空 → 空链（不自适应/BUILTIN 补足），llm 阶段报无模型\n      const chain = buildTryChain(cfg.fallback);\n      // 模板体系扩展（2026-08-18 修订）：每模式 2 个内置模板（default=默认模板·只清晰化重述 /\n      // increment=增量模板·保守补充未说的大逻辑/信息，每模式方向不同）+ 每模式多自定义模板\n      // （pick=custom:<index>）；解析见 pure.js resolveTemplateSystem——旧配置（无 pick）自动迁移\n      // （custom+texts 非空仍生效），行为与旧版等价；旧内置键 supplement/dev 按 increment 处理；非法选中回退 T1。\n      // v2.7.0（一键发布）：publish 模式内置专用九章规格 system（custom 模板仍可覆盖）\n      // v3.2.23（提示词集合化）：模式→模板映射由 SKILL_MANIFEST 驱动（prompts/enhance/*/PACKAGE.md frontmatter 声明）\n      const BUILTIN_TEMPLATES = {};\n      for (const _m of Object.keys(SKILL_MANIFEST)) {\n        BUILTIN_TEMPLATES[_m] = [SKILL_MANIFEST[_m].templates.t1, SKILL_MANIFEST[_m].templates.t2];\n      }\n      let system = resolveTemplateSystem(cfg, cfg.mode, BUILTIN_TEMPLATES);\n      // v3.2.19（用户需求·纪律约束模板）：输出纪律无条件追加——所有模式（含自定义模板）\n      // 都必带，从源头约束「只输出优化后的提示词本体」（与 cleanOutput 事后清理互补）\n      system = system + '\\n\\n' + DISCIPLINE_PROMPT;\n      // v3.0（模式重构）：lite 规则检查移除——lite 改为「前 1 轮会话关联参考」（见 retrieve stage）\n      // v2.6.1（记忆链）：rounds 数组（时间序 [{input,output}]，≤MEMORY_ROUNDS_MAX 轮）→\n      // 真多轮消息注入；hasMemory = rounds 非空；开关关 / 预算 0 → 不注入（行为不变）。\n      const memRounds = args && args.memory && Array.isArray(args.memory.rounds)\n        ? args.memory.rounds.filter((r) => r && (r.input || r.output)).slice(-MEMORY_ROUNDS_MAX)\n        : [];\n      const hasMemory = memRounds.length > 0;\n      const memoryActive = shouldInjectMemory(cfg.memory, hasMemory, cfg.context.budgetChars);\n      // v2.7.0（一键发布 · 改动方向代入检索）：delta 提前计算（记忆链轮次时），\n      // 供 publish 网络检索词构造（buildWebQuery）使用；无记忆链 → null（检索词仅主题词）\n      // v2.8.0（实测修正）：publish 的 removed 侧清零（补充式输入下 removed=上一轮规格，\n      // 污染检索词并误导模型——见 filterDeltaForPublish）；hint 与检索词均用过滤后 delta\n      let memDelta = null;\n      if (memoryActive) {\n        const lastOutput = memRounds[memRounds.length - 1].output;\n        memDelta = filterDeltaForPublish(computeEditDelta(lastOutput, text), cfg.mode);\n      }\n      // v2.8.0（一键发布 · 场景路由）：publish 场景判定——会话级缓存固定（首轮判定写入、\n      // 后续轮读取不重判）。判定源：缓存 miss 且记忆链非空 → 最早轮输入（进程重启续作兜底，\n      // 判定源与注入轮次同源，避免增量文本导致场景翻转）；无记忆链 → 当轮 text。\n      // 判定+写入在 system 注入前完成，与 LLM 调用成败无关（scenario 仅依赖判定源）。\n      let scenario = 'generic';\n      if (cfg.mode === 'publish') {\n        const cached = publishScenarioCache.get(sessionId);\n        if (cached) {\n          scenario = cached;\n        } else {\n          const src = memRounds.length > 0 ? memRounds[0].input : text;\n          scenario = detectScenario(src);\n          publishScenarioCache.set(sessionId, scenario);\n        }\n        if (scenario !== 'generic') {\n          system = system + '\\n\\n【场景判定】本次场景判定：' + scenario + '（依据用户输入自动判定；章节适配要求见「场景适配」段；请勿复述本判定行）';\n        }\n        hlog('[enhance] scenario=' + scenario + (cached ? ' cached' : ' judged src=' + (memRounds.length > 0 ? 'rounds[0]' : 'text')));\n      }\n      // v2.7.0（publish 一键发布）：规格长文生成不设限制——maxTokens 省略（provider 默认上限）、\n      // outputLimit=0（collectStream 不截断）、超时放宽至 ≥120s（长文生成耗时）\n      // v2.8.0（实测修正）：120s → 240s——带记忆链 rounds 的多轮规格生成（重负载路径）\n      // 实测 120s 超时（round-2 完整九章 + 融入补充 + 自评），240s 覆盖 4 轮链最坏情况\n      const isPublish = cfg.mode === 'publish';\n      state.cfg = cfg;\n      state.chain = chain;\n      state.system = system;\n      state.memRounds = memRounds;\n      state.hasMemory = hasMemory;\n      state.memoryActive = memoryActive;\n      state.memDelta = memDelta;\n      state.isContinuation = memoryActive && memRounds.length > 0 && memDelta !== null && (memDelta.added.length > 0 || memDelta.removed.length > 0);\n      state.scenario = scenario;\n      state.isPublish = isPublish;\n      // v3.0p 审查（超时/耗时匹配）：链含 effort 时超时自动放宽 ≥120s——实测 effort=max 长草稿\n      // （1500 字）完整生成 42s > 默认 30s → 必超时；无 effort 行为不变\n      // v2.7.0 曾 publish 强制超时 ≥240s / maxTokens=0 / outputLimit=0（规格长文不截断）；\n      // 2026-08-18（用户指令）取消强制——publish 三项参数可调（默认档 60s/4k/16k 按实测覆盖）\n      // v3.1.7（用户需求·超时无限制）：cfg.timeoutMs=0（无限制）不被 effort 放宽覆盖——保持 0 不挂超时\r\n      // P0-b（2026-10-12 · 单一事实源）：公式抽出为 resolveEnhanceTimeoutMs（pure.js），\r\n      // 与 enhance handler 在准备阶段之前挂计时器时用的是**同一个函数**——杜绝两处漂移。\r\n      state.timeoutMs = resolveEnhanceTimeoutMs(cfg, chain);\n      state.maxTokens = cfg.maxTokens;\n      state.outputLimit = cfg.outputLimit;\n      return state;\n    }\n\n    // ---- stage: retrieve——V2 上下文构建 / 检索 ----\n    // ---- v3.0：会话历史提取（listEvents/filterEvents → extractHistory；失败/不可用 → []）----\n    async function fetchSessionHistory(sessionId, state) {\n      const sq = ctx.get('sessionQuery');\n      if (!sq || typeof sq.listEvents !== 'function' || typeof sq.filterEvents !== 'function') return [];\n      // v3.0p 审查（超时/耗时匹配）：会话历史提取补超时保护（10s，超时/失败 → [] 不阻断）\n      // P0-b 修正（2026-10-12 · 第三轮 · 独立复核 blocker）：原先 histTimer **只置标志位**，\n      // 而 `await sq.readSurface(...)` / `await sq.listEvents(...)` 会一直等到调用自己返回\n      // ⇒ 慢的会话读取可越过钳后超时、吃掉总预算并侵蚀生成额度（复核实测：readSurface 23s/24s/30s\n      // ⇒ 改后 TIMEOUT、genCalls=0，HEAD 为 ok:true）。\n      // 现统一到 startWaitAbort（race + dispose，机制与 LLM 腿的 startHelperAbort 同源）：\n      // 超时即**不再等待**该调用，并按上游「超时 → 跳过检索段」语义返回 []，同时登记降级。\n      const waitAbort = startWaitAbort(ctx.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);\n      try {\n        // v3.1.3（用户需求·仅结论参考）：优先 readSurface（完整事件，保留 content 块结构）\n        // → 结论提取（仅 text 块，丢弃思考/工具调用/系统注入）；旧 listEvents+filterEvents\n        // 路径的文档文本为预拼接语义文本（含工具参数），仅作 readSurface 缺失时的兜底。\n        if (typeof sq.readSurface === 'function') {\n          const surface = await waitAbort.race(sq.readSurface(sessionId));\n          if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }\n          const events = extractHistoryConclusions(surface && surface.events);\n          hlog('[enhance] v3 history events=' + events.length + ' conclusion-only');\n          return events;\n        }\n        const records = await waitAbort.race(sq.listEvents(sessionId));\n        if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }\n        const msgSeqs = [];\n        for (let i = records.length - 1; i >= 0 && msgSeqs.length < V2_MSG_SEQ_SCAN; i--) {\n          const r = records[i];\n          const t = String(r && r.type || '');\n          if (t === 'user/message' || t === 'assistant/message') msgSeqs.push(r && r.seq);\n        }\n        if (msgSeqs.length === 0) return [];\n        const minSeq = msgSeqs[msgSeqs.length - 1];\n        const docs = await waitAbort.race(sq.filterEvents(sessionId, [{ kind: 'seq', from: minSeq }]));\n        if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }\n        const events = extractHistory(docs, V2_HISTORY_LIMIT);\n        hlog('[enhance] v3 history events=' + events.length);\n        return events;\n      } catch (e) {\n        hlog('[enhance] v3 history failed', e && e.message ? e.message : e);\n        return [];\n      } finally {\n        waitAbort.dispose();\n      }\n    }\n\n    // ---- v3.0：LLM 关联性判定（RELEVANCE_PROMPT 占位替换；10s 超时；失败/解析失败 → 不相关）----\n    async function judgeRelevance(historyText, currentText, entry, state) {\r\n      if (llm === undefined || !entry) { markDegraded(state, 'relevance'); return { related: false, reason: 'no-llm' }; }\r\n      // P0-b：辅助调用并入主预算——超预算直接跳过（记降级，不阻断主流程）\r\n      if (budgetExhausted(state)) { markDegraded(state, 'relevance-budget'); hlog('[enhance] v3 relevance skipped budget-exhausted'); return { related: false, reason: 'budget-exhausted' }; }\r\n      const system = RELEVANCE_PROMPT\r\n        .replace('{history}', String(historyText || ''))\r\n        .replace('{current}', String(currentText || ''));\r\n      let timedOut = false;\r\n      // P0-b：自身 10s 超时钳到剩余预算内（不越过主预算）\r\n      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）\n      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);\n      try {\n        const stream = llm.stream({\n          provider: entry.provider,\n          model: entry.model,\n          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时\n          maxTokens: RELEVANCE_MAX_TOKENS,\n          system,\n          messages: [{\n            id: 'enhance-relevance',\n            role: 'user',\n            content: [{ type: 'text', text: '请依据上述规则判断关联性。' }],\n            source: { kind: 'user' },\n          }],\n        });\n        const iterator = stream[Symbol.asyncIterator]();\n        abortCtl.attach(iterator);\n        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);\n        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝\n        collectP.catch(() => { /* 落败方 */ });\n        const result = await abortCtl.race(collectP);\n        timedOut = abortCtl.timedOut();\r\n        // P0-e（消费点 2/6 之一）：max-tokens 现返回可区分 kind 'maxtokens'（不再是 EMPTY_RESPONSE）；\r\n        // 判定类辅助调用**按原样透传**——非 'ok' 一律判失败（显式声明，不静默沿用旧兜底）。\r\n        if (!timedOut && result.kind === 'ok') {\r\n          const parsed = parseRelevance(result.text);\r\n          if (parsed) return parsed;\r\n        }\r\n        // P0-d：判定失败/超时 → 记降级（结果在无参考状态下生成，用户须可见）\r\n        markDegraded(state, timedOut ? 'relevance-timeout' : (result.kind === 'maxtokens' ? 'relevance-truncated' : 'relevance-unparsed'));\r\n        hlog('[enhance] v3 relevance ' + (timedOut ? 'timeout' : 'unparsed'));\r\n      } catch (e) {\r\n        markDegraded(state, 'relevance-failed');\r\n        hlog('[enhance] v3 relevance failed', e && e.message ? e.message : e);\n      } finally {\n        abortCtl.dispose();\n      }\n      return { related: false, reason: 'judge-failed' };\n    }\n\n\n    // ---- v3.0p（publish 多步检索）：LLM 检索主题规划（WEBSEARCH_PLAN_PROMPT 占位替换；\n    // 10s 超时；失败/解析失败 → null → retrieve 降级 buildWebQuery 单 query）----\n    async function planWebSearch(text, memoText, scenario, entry, state) {\r\n      if (llm === undefined || !entry) { markDegraded(state, 'webplan'); return null; }\r\n      // P0-b：辅助调用并入主预算——超预算直接跳过（降级为单 query 路径）\r\n      if (budgetExhausted(state)) { markDegraded(state, 'webplan-budget'); hlog('[enhance] v3p web-plan skipped budget-exhausted'); return null; }\r\n      const system = WEBSEARCH_PLAN_PROMPT\r\n        .replace('{text}', String(text || ''))\r\n        .replace('{memo}', String(memoText || '（暂无）'))\r\n        .replace('{scenario}', String(scenario || 'generic'));\r\n      let timedOut = false;\r\n      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）\n      const abortCtl = startHelperAbort(state, WEB_PLAN_TIMEOUT_MS);\n      try {\n        const stream = llm.stream({\n          provider: entry.provider,\n          model: entry.model,\n          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时\n          maxTokens: WEB_PLAN_MAX_TOKENS,\n          system,\n          messages: [{\n            id: 'enhance-webplan',\n            role: 'user',\n            content: [{ type: 'text', text: '请输出检索主题规划。' }],\n            source: { kind: 'user' },\n          }],\n        });\n        const iterator = stream[Symbol.asyncIterator]();\n        abortCtl.attach(iterator);\n        const collectP = collectStream(iterator, WEB_PLAN_OUTPUT_LIMIT);\n        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝\n        collectP.catch(() => { /* 落败方 */ });\n        const result = await abortCtl.race(collectP);\n        timedOut = abortCtl.timedOut();\r\n        // P0-e（消费点 3/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。\r\n        if (!timedOut && result.kind === 'ok') {\r\n          const parsed = parseSearchPlan(result.text);\r\n          if (parsed) return parsed;\r\n        }\r\n        markDegraded(state, timedOut ? 'webplan-timeout' : (result.kind === 'maxtokens' ? 'webplan-truncated' : 'webplan-unparsed'));\r\n        hlog('[enhance] v3p web-plan ' + (timedOut ? 'timeout' : 'unparsed'));\r\n      } catch (e) {\r\n        markDegraded(state, 'webplan-failed');\r\n        hlog('[enhance] v3p web-plan failed', e && e.message ? e.message : e);\n      } finally {\n        abortCtl.dispose();\n      }\n      return null;\n    }\n    // ---- v3.0（S3）：工作区文件检索（扩展名过滤 + 关键词排序 + 摘要；2s 超时降级）----\n    const DOC_FILE_RE = /\\.md$/i;\n    const CODE_FILE_RE = /\\.(?:js|ts|jsx|tsx|py|go|rs|java|cpp|c|h|cs|rb|php|sql|sh|vue|html|css|json|yaml|yml|toml)$/i;\n    async function searchWorkspaceFiles(extRe, keywords, maxFiles, maxDepth, paths) {\n      const fsSvc = ctx.get('fs');\n      const sp = ctx.get('sandboxPolicy');\n      const root = sp && sp.workspaceRoot;\n      if (!fsSvc || !root || typeof fsSvc.listDir !== 'function' || typeof fsSvc.resolve !== 'function' || typeof fsSvc.readText !== 'function') return [];\n      // P0-b 修正（2026-10-12 · 第三轮）：标志位 → race+dispose（与 v2SearchWorkspace 同一机制）。\n      // 慢的 fs 调用此前会越过 V2_WORKSPACE_TIMEOUT_MS 一直等 ⇒ 侵蚀生成额度。\n      const waitAbort = startWaitAbort(ctx.timer, V2_WORKSPACE_TIMEOUT_MS);\n      const aborted = () => waitAbort.timedOut();\n      try {\n        let rootTarget;\n        try { rootTarget = await waitAbort.race(fsSvc.resolve(root)); } catch (e) { return []; }\n        if (waitAbort.timedOut()) return [];\n        const files = [];\n        const walk = async (target, rel, level) => {\n          if (aborted() || files.length >= SCAN_FILE_LIST_MAX || level > maxDepth) return;\n          let entries;\n          try { entries = await waitAbort.race(fsSvc.listDir(target)); } catch (e) { return; }\n          if (waitAbort.timedOut()) return;\n          for (const en of entries || []) {\n            if (aborted()) return;\n            const name = en && en.name;\n            if (!name) continue;\n            if (en.type === 'directory') {\n              if (V2_WORKSPACE_IGNORE_DIRS.has(name)) continue;\n              const sub = en.target;\n              if (sub) await walk(sub, rel ? rel + '/' + name : name, level + 1);\n              continue;\n            }\n            const p = rel ? rel + '/' + name : name;\n            if (extRe.test(name) && !shouldIgnoreFile(p)) files.push(p);\n          }\n        };\n        await walk(rootTarget, '', 1);\n        const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);\n        // 关键词为空（短文本提不出词）→ 不排序直接取前 maxFiles；\n        // 关键词非空但名称 0 命中 → 内容兜底扫描（中文关键词 vs 英文文件名的老问题，\n        // 与 v2SearchWorkspace content-fallback 同策略）\n        let ranked = kws.length > 0 ? rankFiles(files, kws, 10).map((c) => c.path) : files.slice(0, maxFiles);\n        if (ranked.length === 0 && kws.length > 0) {\n          const scored = [];\n          // 中文组合词分段匹配（「登录功能」→「登录」/「功能」），避免 4 字组合词 vs 内容子串失配\n          const kwSegs = [];\n          for (const k of kws) {\n            const kl = String(k).toLowerCase();\n            kwSegs.push(kl);\n            for (const sg of splitCnSegments(kl)) {\n              if (sg.length >= 2 && !kwSegs.includes(sg)) kwSegs.push(sg);\n            }\n            // 2 字前缀兜底（组合词切不开时，如「登录功能」→「登录」）\n            if (kl.length >= 2 && !kwSegs.includes(kl.slice(0, 2))) kwSegs.push(kl.slice(0, 2));\n          }\n          for (const rel of files.slice(0, 8)) {\n            if (aborted()) break;\n            try {\n              const tgt = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));\n              if (waitAbort.timedOut()) break;\n              const text = await waitAbort.race(fsSvc.readText(tgt));\n              if (waitAbort.timedOut()) break;\n              let hits = 0;\n              for (const ln of text.split('\\n')) {\n                if (kwSegs.length > 0 && kwSegs.some((sg) => ln.toLowerCase().includes(sg))) hits++;\n                if (hits >= 8) break;\n              }\n              if (hits > 0) scored.push({ path: rel, hits });\n            } catch (e) { /* 跳过 */ }\n          }\n          scored.sort((a, b) => b.hits - a.hits);\n          ranked = scored.slice(0, maxFiles).map((s) => s.path);\n        }\n        // 最终兜底：内容仍不匹配（中文关键词 vs 英文代码/文件名的语义鸿沟）→ 取前 N 个\n        // （开发环境已确认或 md 文档场景下文件有限，全取参考优于空参考）\n        if (ranked.length === 0) ranked = files.slice(0, maxFiles);\n        // v3.0v2：项目地图指向路径优先（codePaths 前缀命中排前，不足补全量）\n        if (paths && paths.length > 0 && files.length > 0) {\n          const prefixed = files.filter((f) => paths.some((p) => f === p || f.startsWith(p + '/')));\n          const rest = files.filter((f) => !prefixed.includes(f));\n          ranked = prefixed.concat(rest).slice(0, maxFiles);\n        }\n        const out = [];\n        for (const rel of ranked.slice(0, maxFiles)) {\n          if (aborted()) break;\n          try {\n            const tgt = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));\n            if (waitAbort.timedOut()) break;\n            const text = await waitAbort.race(fsSvc.readText(tgt));\n            if (waitAbort.timedOut()) break;\n            out.push({ path: rel, snippet: snippetFromLines(text.split('\\n'), kws, SNIPPET_BUDGET) });\n          } catch (e) { /* 跳过 */ }\n        }\n        return out;\n      } finally {\n        waitAbort.dispose();\n      }\n    }\n\n    // ---- v3.0v2：smart 工作区阶段（门槛：有 .md + 相关文档命中 + 项目地图结构）----\n    // 返回 { block, enteredThird }——enteredThird 决定 SMART_TAIL（调整方案）是否追加。\n    async function enhanceSmartWorkspace(state, text, chain0, rbudget) {\n      // v3.1.8（用户需求·预算真正生效）：smart 工作区规模随预算伸缩（BUDGET_RETRIEVE_TABLE）——\n      // 文档扫描数/深度、文档与代码内容上限随档位递增；预算 0 由调用方跳过（不进入本函数）。\n      const kws = extractKeywords(text, []);\n      const docs = await searchWorkspaceFiles(DOC_FILE_RE, kws, rbudget.smartDocs, rbudget.smartDepth);\n      if (docs.length === 0) {\n        hlog('[enhance] v3 smart no-md');\n        return { block: state.v2Block, enteredThird: false };\n      }\n      const docsText = docs.map((d) => '📄 ' + d.path + '\\n' + d.snippet).join('\\n\\n').slice(0, rbudget.smartChars);\n      // B+C 合并：一次 LLM 调用——检索相关文档 + 分析项目地图结构\n      if (state.rec) setProgress(state.rec, STAGE_FILES, 'docs');\n      const analysis = await analyzeDocsRelevance(docsText, text, state.v2Block || '', chain0, state);\n      if (!analysis || analysis.relatedDocs.length === 0) {\n        hlog('[enhance] v3 smart no-related-doc');\n        return { block: state.v2Block, enteredThird: false };\n      }\n      const docPart = (state.v2Block ? state.v2Block + '\\n\\n' : '') + '【项目文档参考】\\n' +\n        analysis.relatedDocs.map((d) => '📄 ' + d.path + '\\n' + d.excerpt).join('\\n\\n');\n      if (!analysis.hasProjectMap) {\n        hlog('[enhance] v3 smart no-project-map reason=' + analysis.reason);\n        return { block: docPart, enteredThird: false };\n      }\n      // 第三步：代码文档检索（项目地图指向路径优先）\n      hlog('[enhance] v3 smart project-map paths=' + JSON.stringify(analysis.codePaths));\n      if (state.rec) setProgress(state.rec, STAGE_FILES, 'code');\n      const codes = await searchWorkspaceFiles(CODE_FILE_RE, kws, 3, 3, analysis.codePaths);\n      const codeText = codes.map((c) => '📄 ' + c.path + '\\n' + c.snippet).join('\\n\\n').slice(0, rbudget.smartCodeChars);\n      return { block: codeText ? docPart + '\\n\\n【相关代码参考】\\n' + codeText : docPart, enteredThird: true };\n    }\n\n    // ---- v3.0v2：提示词开发意向判定（DEV_INTENT_PROMPT；10s 超时降级非开发意向）----\n    async function judgeDevIntent(text, sessionRef, entry, state) {\r\n      if (llm === undefined || !entry) { markDegraded(state, 'intent'); return { isDevIntent: false, reason: 'no-llm' }; }\r\n      if (budgetExhausted(state)) { markDegraded(state, 'intent-budget'); hlog('[enhance] v3 intent skipped budget-exhausted'); return { isDevIntent: false, reason: 'budget-exhausted' }; }\n      const system = DEV_INTENT_PROMPT\r\n        .replace('{prompt}', String(text || ''))\r\n        .replace('{session}', String(sessionRef || ''));\r\n      let timedOut = false;\r\n      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）\n      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);\n      try {\n        const stream = llm.stream({\n          provider: entry.provider,\n          model: entry.model,\n          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时\n          maxTokens: RELEVANCE_MAX_TOKENS,\n          system,\n          messages: [{\n            id: 'enhance-intent',\n            role: 'user',\n            content: [{ type: 'text', text: '请依据上述规则判断。' }],\n            source: { kind: 'user' },\n          }],\n        });\n        const iterator = stream[Symbol.asyncIterator]();\n        abortCtl.attach(iterator);\n        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);\n        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝\n        collectP.catch(() => { /* 落败方 */ });\n        const result = await abortCtl.race(collectP);\n        timedOut = abortCtl.timedOut();\r\n        // P0-e（消费点 4/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。\r\n        if (!timedOut && result.kind === 'ok') {\r\n          const parsed = parseIntent(result.text);\r\n          if (parsed) return parsed;\r\n        }\r\n        markDegraded(state, timedOut ? 'intent-timeout' : (result.kind === 'maxtokens' ? 'intent-truncated' : 'intent-unparsed'));\r\n        hlog('[enhance] v3 intent ' + (timedOut ? 'timeout' : 'unparsed'));\r\n      } catch (e) {\r\n        markDegraded(state, 'intent-failed');\r\n        hlog('[enhance] v3 intent failed', e && e.message ? e.message : e);\n      } finally {\n        abortCtl.dispose();\n      }\n      return { isDevIntent: false, reason: 'judge-failed' };\n    }\n\n    // ---- v3.0v2：文档检索 + 项目地图合并分析（DOC_ANALYSIS_PROMPT 一次调用）----\n    async function analyzeDocsRelevance(docsText, text, sessionRef, entry, state) {\r\n      if (llm === undefined || !entry) { markDegraded(state, 'docs'); return null; }\r\n      if (budgetExhausted(state)) { markDegraded(state, 'docs-budget'); hlog('[enhance] v3 doc-analysis skipped budget-exhausted'); return null; }\n      const system = DOC_ANALYSIS_PROMPT\r\n        .replace('{docs}', String(docsText || ''))\r\n        .replace('{prompt}', String(text || ''))\r\n        .replace('{session}', String(sessionRef || ''));\r\n      let timedOut = false;\r\n      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）\n      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);\n      try {\n        const stream = llm.stream({\n          provider: entry.provider,\n          model: entry.model,\n          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时\n          maxTokens: RELEVANCE_MAX_TOKENS,\n          system,\n          messages: [{\n            id: 'enhance-docanalysis',\n            role: 'user',\n            content: [{ type: 'text', text: '请依据上述规则分析。' }],\n            source: { kind: 'user' },\n          }],\n        });\n        const iterator = stream[Symbol.asyncIterator]();\n        abortCtl.attach(iterator);\n        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);\n        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝\n        collectP.catch(() => { /* 落败方 */ });\n        const result = await abortCtl.race(collectP);\n        timedOut = abortCtl.timedOut();\r\n        // P0-e（消费点 5/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。\r\n        if (!timedOut && result.kind === 'ok') {\r\n          const parsed = parseDocsAnalysis(result.text);\r\n          if (parsed) return parsed;\r\n        }\r\n        markDegraded(state, timedOut ? 'docs-timeout' : (result.kind === 'maxtokens' ? 'docs-truncated' : 'docs-unparsed'));\r\n        hlog('[enhance] v3 doc-analysis ' + (timedOut ? 'timeout' : 'unparsed'));\r\n      } catch (e) {\r\n        markDegraded(state, 'docs-failed');\r\n        hlog('[enhance] v3 doc-analysis failed', e && e.message ? e.message : e);\n      } finally {\n        abortCtl.dispose();\n      }\n      return null;\n    }\n    // ---- stage: retrieve——v3.0 检索策略分发（rounds 窗口判定 / v2 旧管道 / none）----\n    async function enhanceStageRetrieve(state) {\n      const cfg = state.cfg;\n      const text = state.text;\n      const sessionId = state.sessionId;\n      const rec = state.rec;\n      const row = SKILL_MANIFEST[cfg.mode].retrieve || SKILL_MANIFEST[DEFAULT_MODE].retrieve; // v3.2.23 retrieve 声明化（prompts/*/PACKAGE.md）\n      state.v2Block = '';\n      state.v2Log = 'none';\n      if (state.isContinuation) {\n        state.v2Log = 'continuation-skip';\n        return state;\n      }\n      if (row.kind === 'rounds' && row.windows.length > 0) {\n        // v3.1.8（用户需求·预算真正生效）：rounds 模式消费上下文预算——budget 0 = 跳过检索\n        // （不注入参考，等价 base 直发）；budget > 0 时注入上限随档位伸缩（BUDGET_RETRIEVE_TABLE）。\n        const rbudget = resolveRetrieveBudget(cfg.mode, cfg.context && cfg.context.budgetChars ? cfg.context.budgetChars : 0);\n        if (rbudget.roundsChars > 0) {\n          // v3.0：会话轮次窗口关联检索——逐窗口 LLM 判定，命中即停并注入参考；\n          // 窗口越界（历史不足）跳过；全不中 → 无参考（不阻断主流程）。\n          // 2026-08-18（用户需求·步骤补充）：rounds 模式补「读取会话」进度（与 publish 一致）\n          if (state.rec) setProgress(state.rec, STAGE_HISTORY);\n          const events = await fetchSessionHistory(sessionId, state);\n          const chain0 = state.chain && state.chain.length > 0 ? state.chain[0] : null;\n          for (let wi = 0; wi < row.windows.length; wi++) {\n            const win = row.windows[wi];\n            if (rec.cancelled || rec.timedOut) break;\n            const winText = splitHistoryRounds(events, win[0], win[1]).join('\\n');\n            if (winText === '') {\n              hlog('[enhance] v3 window empty rounds=' + win[0] + '-' + win[1]);\n              continue;\n            }\n            setProgress(rec, STAGE_ANALYZE, 'judge', null, wi + 1, row.windows.length);\n            const judge = await judgeRelevance(winText, text, chain0, state);\n            if (judge.related) {\n              state.v2Block = '【相关会话参考（仅吸收明确需求，禁止复述）】\\n' + winText.slice(0, rbudget.roundsChars);\n              state.v2Log = 'rounds=' + win[0] + '-' + win[1] + ' chars=' + winText.length + ' inject=' + Math.min(winText.length, rbudget.roundsChars) + ' reason=' + judge.reason;\n              hlog('[enhance] v3 window hit rounds=' + win[0] + '-' + win[1] + ' reason=' + judge.reason);\n              break;\n            }\n            hlog('[enhance] v3 window miss rounds=' + win[0] + '-' + win[1] + ' reason=' + judge.reason);\n          }\n          // v3.0v2：smart——窗口判定后先判开发意向（非开发意向直接停，不进工作区）；\n          // 开发意向 → 工作区阶段（.md + 相关文档命中 + 项目地图三门槛），\n          // 仅进入第三步（代码阶段）才追加 SMART_TAIL（调整方案输出）\n          if (SKILL_MANIFEST[cfg.mode].sources.indexOf('workspace') !== -1) {\n            setProgress(rec, STAGE_ANALYZE, 'intent');\n            const intent = await judgeDevIntent(text, state.v2Block || '', chain0, state);\n            if (!intent.isDevIntent) {\n              hlog('[enhance] v3 smart not-dev-intent reason=' + intent.reason);\n            } else {\n              hlog('[enhance] v3 smart dev-intent reason=' + intent.reason);\n              const ws = await enhanceSmartWorkspace(state, text, chain0, rbudget);\n              state.v2Block = ws.block;\n              if (ws.enteredThird) {\n                state.system = state.system + '\\n\\n' + SMART_TAIL_PROMPT;\n                hlog('[enhance] v3 smart tail injected');\n              }\n            }\n          }\n        } else {\n          // 预算 0：rounds 检索跳过（不注入参考；smart 工作区同样不进入）\n          state.v2Log = 'rounds-skip budget=0';\n        }\n      } else if (row.kind === 'v2') {\n        // publish：v2 旧管道 + v3.0p 多步网络检索（LLM 规划主题 → 逐主题搜索 → 跨轮记忆回注）\n        const memoRec = publishWebMemo.get(sessionId);\n        const memoText = memoRec && memoRec.memo ? memoRec.memo : '';\n        const memoTopics = memoRec && Array.isArray(memoRec.topics) ? memoRec.topics : [];\n        const chain0 = state.chain && state.chain.length > 0 ? state.chain[0] : null;\n        const budget = cfg.context && cfg.context.budgetChars ? cfg.context.budgetChars : 0;\n        // v3.0p：预算 > 0 才启用检索（与「上下文预算需 > 0 才启用检索」联动语义一致）\n        setProgress(rec, STAGE_FILES, 'plan');\n        // P0-b：预算耗尽 → 直接跳过规划（planWebSearch 内部亦自检，双保险）\r\n        const plan = (budget > 0 && !budgetExhausted(state)) ? await planWebSearch(text, memoText, state.scenario, chain0, state) : (budget > 0 ? (markDegraded(state, 'webplan-budget'), null) : null);\n        hlog('[enhance] v3p web-plan ' + (budget <= 0 ? 'skipped budget=0' : (plan ? 'topics=' + plan.topics.map((t) => t.query).join('|') : 'none→legacy')));\n        // v3.0p：规划主题与已检索主题去重（LLM 未遵从提示词时的硬过滤；过滤后为空 → 降级单 query）\n        const freshPlan = plan && budget > 0 ? plan.topics.filter((t) => memoTopics.indexOf(String(t && t.query || '').trim()) === -1) : null;\n        const v2 = await buildV2ContextBlock({\r\n          llm: ctx.get('llm'),\r\n          sessionQuery: ctx.get('sessionQuery'),\r\n          sandboxPolicy: ctx.get('sandboxPolicy'),\r\n          fs: ctx.get('fs'),\r\n          timer: ctx.timer,\r\n          chain: state.chain,\r\n          web: ctx.get('web'),\r\n          delta: state.memDelta,\r\n          scenario: state.scenario,\r\n          webPlan: freshPlan && freshPlan.length > 0 ? freshPlan : null,\r\n          webMemo: memoText,\r\n          // P0-b（2026-10-12）：publish 的 v2 旧管道（阶段 A 任务分析 15s / 阶段 B 2s /\r\n          // 网络检索 10s）同属准备阶段——把主预算截止时刻交给它，内部各调用据此钳到剩余预算。\r\n          budgetDeadline: state.budgetDeadline,\r\n          budgetMs: state.budgetMs,\r\n          // P0-d（2026-10-12 · 独立复核 medium）：v2 管道内的辅助调用降级回传\n          // （第 5 个辅助点 v2ResolveProgress 经此暴露，不再只写 hlog）\n          onDegrade: (kind) => { markDegraded(state, kind); },\n        }, sessionId, text, cfg, (st, detail) => {\n          rec.stage = st;\n          if (detail && typeof detail === 'object') {\n            rec.detailKey = detail.key || '';\n            rec.detailArgs = detail.args || null;\n            rec.step = detail.step || 0;\n            rec.total = detail.total || 0;\n          } else {\n            rec.detailKey = '';\n            rec.detailArgs = null;\n            rec.step = 0;\n            rec.total = 0;\n          }\n        });\n        state.v2Block = v2.block;\n        state.v2Log = v2.log;\n        // v3.0p：跨轮检索记忆更新——仅成功命中的主题入已检索列表（失败/超时不占位），\n        // 主题去重（≤WEB_MEMO_TOPICS_MAX）+ 要点摘要累积（≤WEB_MEMO_MAX，保留最新）\n        const hitTopics = Array.isArray(v2.webTopics) ? v2.webTopics.filter((t) => t && t.hits > 0) : [];\n        if (hitTopics.length > 0) {\n          const merged = memoTopics.concat(hitTopics.map((t) => t.query)).filter((q, i, a) => q && a.indexOf(q) === i).slice(-WEB_MEMO_TOPICS_MAX);\n          const memo = (memoText ? memoText + '\\n' : '') + (v2.webMemoText || '');\n          publishWebMemo.set(sessionId, { topics: merged, memo: memo.slice(-WEB_MEMO_MAX) });\n          hlog('[enhance] v3p memo topics=' + merged.length + ' chars=' + memo.slice(-WEB_MEMO_MAX).length);\n        }\n      }\n      // v3.2.24（规则落点 L2）：参考使用规则改为条件注入——参考块/记忆命中才追加（v3.2.20 并入 discipline 无条件，\n      // 现拆为独立 REFERENCE_GUIDE 提示词文件按需加载，无参考场景省 tokens）；L0 纪律保持精简。\n      if (state.v2Block !== '' || state.memoryActive) state.system = state.system + '\\n\\n' + REFERENCE_GUIDE;\n      return state;\n    }    // ---- stage: assemble——消息组装 / 日志 ----\n    async function enhanceStageAssemble(state) {\n      const args = state.args;\n      const sessionId = state.sessionId;\n      const seq = state.seq;\n      const text = state.text;\n      // 2026-08-18（用户需求·每模式步骤补充）：assemble 阶段开始即上报进度「组装上下文」\n      if (state.rec) setProgress(state.rec, STAGE_CONTEXT);\n      const cfg = state.cfg;\n      const chain = state.chain;\n      const system = state.system;\n      const memRounds = state.memRounds;\n      const memoryActive = state.memoryActive;\n      const memDelta = state.memDelta;\n      const v2Block = state.v2Block;\n      const v2Log = state.v2Log;\n      const isContinuation = state.isContinuation === true;\n      const timeoutMs = state.timeoutMs;\n      const maxTokens = state.maxTokens;\n      const outputLimit = state.outputLimit;\n      // v2.6.1：消息组装——记忆链经 buildChatMessages 成为真多轮 user/assistant 消息，\n      // 最终 user 消息 = 本轮修改摘要 + 模式块 + 原文包裹；无记忆 → 单 user 消息（旧行为）。\n      let memoryLog = '';\n      // v2.8.0（一键发布 · 实测修正）：publish 用中性用户包装（wrapPublishText），\n      // 其余模式沿用「请优化以下提示词」包装（行为不变）\n      const wrappedText = state.isPublish ? wrapPublishText(text) : wrapUserText(text);\n      let finalText = v2Block !== '' ? v2Block + '\\n\\n' + wrappedText : wrappedText;\n      if (isContinuation) {\n        state.system = system + '\\n\\n' + CONTINUE_PROMPT;\n        const hint = buildMemoryDeltaHint(memDelta);\n        finalText = '【本轮修改】（主要优化方向）\\n' + (hint !== '' ? hint : '请基于当前草稿继续完善。') + '\\n\\n【当前提示词】\\n\"\"\"\\n' + text + '\\n\"\"\"\\n\\n请基于以上修改继续完善，输出完整更新后的提示词。';\n      }\n      let messages;\n      if (memoryActive) {\n        const hint = buildMemoryDeltaHint(memDelta);\n        if (hint !== '' && !isContinuation) finalText = hint + '\\n\\n' + finalText;\n        const built = buildChatMessages(memRounds, finalText, 'enhance-' + sessionId + '-' + seq, cfg.context.budgetChars);\n        messages = built.messages;\n        memoryLog = 'memory rounds=' + memRounds.length + ' chars=' + built.memChars + ' delta=' + (hint !== '' ? 'yes' : 'none');\n      } else {\n        messages = [{ id: 'enhance-' + sessionId + '-' + seq, role: 'user', content: [{ type: 'text', text: finalText }], source: { kind: 'user' } }];\n      }\n      const modeTag = args && args.seed === true ? cfg.mode + '(seed)' : cfg.mode;\n      const ctxLog = [v2Log === 'none' ? '' : v2Log, memoryLog].filter((s) => s !== '').join('+') || 'none';\n      hlog('[enhance] cfg session=' + sessionId + ' mode=' + modeTag + ' ctx=' + ctxLog + ' chain=' + (chain.length > 0 ? chain.map((f) => f.provider + '/' + f.model).join(',') : '-') + ' timeout=' + timeoutMs + ' maxTokens=' + maxTokens + ' outputLimit=' + outputLimit + ' template=' + (cfg.templatePick && typeof cfg.templatePick === 'object' && cfg.templatePick[cfg.mode] ? cfg.templatePick[cfg.mode] : (cfg.templateMode === 'custom' ? 'custom' : 'builtin')));\n      state.messages = messages;\n      return state;\n    }\n\n    // ---- stage: llm——模型链调用 / 流式收集 / 结果清理 ----\n    async function enhanceStageLlm(state) {\n      const sessionId = state.sessionId;\n      const seq = state.seq;\n      const rec = state.rec;\n      let chain = state.chain.slice();\n      const system = state.system;\n      const messages = state.messages;\n      const isPublish = state.isPublish;\n      const maxTokens = state.maxTokens;\n      const outputLimit = state.outputLimit;\n      let lastFailure = null;\n      // 2026-08-18（用户需求·删内置兜底链）：模型链为空 → 明确报「未配置模型」（不自适应补足）\n      if (chain.length === 0) {\n        state.result = { ok: false, code: 'NO_MODEL', message: friendlyMessage({ code: 'NO_MODEL' }) };\n        return state;\n      }\n      // v3.3.3（2026-08-27 用户实测·增强易断链修复）：外层 pass 循环——首轮整链耗尽后\n      // 整体重试一次（最多 2 pass），瞬时限流/慢首字/网络抖动自愈；重试轮不再挂看门狗、\n      // 不走探测缓存（直接真实生成），杜绝「探测判死 → 冻结整链 → 连续失败」；\n      // 总预算仍由外层 timeoutMs 计时器兜底（rec.timedOut 立即中断，不无限重试）。\n      for (let pass = 0; pass < 2; pass++) {\n      for (let i = 0; i < chain.length; i++) {\n        const entry = chain[i];\n        if (rec.cancelled || rec.timedOut) {\n          state.result = { ok: false, code: rec.timedOut ? 'TIMEOUT' : 'ABORTED', message: friendlyMessage({ code: rec.timedOut ? 'TIMEOUT' : 'ABORTED' }) };\n          return state;\n        }\n        hlog('[enhance] try session=' + sessionId + ' provider=' + entry.provider + ' model=' + entry.model + (entry.reasoningEffort ? ' effort=' + entry.reasoningEffort : '') + ' seq=' + seq);\n        // v3.2.4（用户需求）：模型序号 = 用户设置（fallback 链）中的位置——buildTryChain\r\n        // 会去重/过滤导致 chain 索引偏移；用 fallback 原始序号，设置里第 N 条就显示 N（自动随数量）\r\n        const fb = state.cfg && Array.isArray(state.cfg.fallback) ? state.cfg.fallback : [];\r\n        let stepNum = i + 1;\r\n        for (let fi = 0; fi < fb.length; fi++) {\r\n          const it = fb[fi];\r\n          if (it && typeof it === 'object' && String(it.provider).trim() === entry.provider && String(it.model).trim() === entry.model) {\r\n            stepNum = fi + 1;\r\n            break;\r\n          }\r\n        }\r\n        setProgress(rec, STAGE_LLM, i > 0 ? 'retry' : '', null, stepNum, fb.length > 0 ? fb.length : chain.length);\n        let result = null;\r\n        let streamThrowFailure = null;\r\n        let watchFired = false;\r\n        // P0-a（2026-10-12 · 补退避重试）：插件直调 ctx.llm.stream() 站在官方设计上**没有可靠性层**的位置——\r\n        // 宿主退避挂在 agent/request-error 水位（由 agent-loop 生产），插件自己消费流吃不到（官方明文：\r\n        // 直接调用 ctx.llm.stream() 的调用方仍然只尝试一次）。此处按官方语义在其外层补一层退避重试：\r\n        //   · 退避参数**不硬编码** —— 调 ctx.llm.providerRetryPolicy(provider) 取官方**已解析**的策略\r\n        //     （**平铺**结构：{mode,maxRetries,retryableCodes,initialDelayMs,maxDelayMs,jitterRatio}）；\r\n        //   · 可重试码集同样**从策略取**（policy.retryableCodes），不照抄常量；\r\n        //   · 退避公式与官方 dsh-llm-retry localDelay 逐式一致（见 pure.js computeBackoffDelayMs）；\r\n        //   · 策略不可得（旧宿主/未注册路由）→ 不重试，行为回到「只尝试一次」（零回归）。\r\n        for (let attempt = 0; ; attempt++) {\r\n          if (rec.cancelled || rec.timedOut) break;\r\n          let stream;\r\n          try {\r\n            stream = llm.stream({\r\n              provider: entry.provider,\r\n              model: entry.model,\r\n              ...(entry.reasoningEffort ? { reasoningEffort: entry.reasoningEffort } : {}),\r\n              system,\r\n              // v2.7.0（publish）：maxTokens<=0 省略字段 → provider 默认上限（不设限制）\r\n              // v2.9.0-fix（实测确证）：reasoning 模式（带 effort）下思考过程消耗 maxTokens\r\n              // 预算——配置的 2000 在长输入 + effort=max 时耗尽 → 空流（EMPTY_RESPONSE）；\r\n              // 自动放宽到 >=8000（保守版；publish 九章规格长文同策略放宽——实测 maxTokens=2000 时空流，v3.2.27 修复）\r\n              ...(entry.reasoningEffort ? { maxTokens: Math.max(maxTokens, 8000) } : (isPublish ? { maxTokens: Math.max(maxTokens, 8000) } : (maxTokens > 0 ? { maxTokens } : {}))),\r\n              // v3.2.21（用户需求·优化结果稳定）：确定性重述任务压低 temperature——不传时用平台默认\r\n              // （随机性高，同一输入每次结果不同）；reasoning 链节由 effort 控制，不传 temperature\r\n              ...(entry.reasoningEffort ? {} : { temperature: 0.3 }),\r\n              messages,\r\n            });\r\n          } catch (e) {\r\n            // v3.1.3（看门狗 + 延迟连通性预检）：llm.stream 同步抛错 = 模型不可达 → 记失败走下一条\r\n            hlog('[enhance] fail session=' + sessionId + ' model=' + entry.model + ' code=STREAM_THROW attempt=' + attempt);\r\n            streamThrowFailure = { code: e && e.code ? String(e.code) : 'STREAM_THROW', message: String(e && e.message ? e.message : e) };\r\n            break;\r\n          }\r\n          const iterator = stream[Symbol.asyncIterator]();\r\n          rec.iterator = iterator;\r\n          // v3.1.3（看门狗 + 延迟连通性预检）：仅首个尝试挂响应看门狗——WATCHDOG_TIMEOUT_MS 内\r\n          // 无任何 chunk → 判首模型不通，中断当前流并进入连通性探测（探测选模型重启生成，\r\n          // 重启不再挂看门狗，防「慢但健康」模型被反复打断成死循环）\r\n          let watchTimer = null;\r\n          watchFired = false;\r\n          if (i === 0 && !state.watchdogDone) {\r\n            // P0-c（2026-10-12）：看门狗阈值按实测 TTFT 重算（= ceil(9300×2/1000)×1000 = 19s），\r\n          // 但**必须按剩余主预算钳制**——\r\n            // 否则放宽阈值会掩盖真挂死（一个不响应的路由可以一直在预算内耗着）。钳制后：\r\n            // ① 慢但健康（TTFT ≤ 9.3s 实测上界）不会被误杀；② 真无响应仍在主预算处被砍（TIMEOUT）。\r\n            const watchBudget = remainingBudgetMs(state);\r\n            const watchMs = watchBudget === Infinity ? WATCHDOG_TIMEOUT_MS : Math.max(0, Math.min(WATCHDOG_TIMEOUT_MS, watchBudget));\r\n            watchTimer = ctx.timer.timeout(() => {\r\n              watchFired = true;\r\n              if (rec.iterator && typeof rec.iterator.return === 'function') {\r\n                try { rec.iterator.return(); } catch (e) { /* 忽略 */ }\r\n              }\r\n            }, watchMs);\r\n          }\r\n          try {\r\n            result = await collectStream(iterator, outputLimit, () => {\r\n              if (watchTimer) { watchTimer(); watchTimer = null; }\r\n            });\r\n          } finally {\r\n            if (watchTimer) watchTimer();\r\n            rec.iterator = null;\r\n          }\r\n          if (watchFired) break;\r\n          // ---- P0-a：退避重试判定（仅对策略声明的可重试码；watchdog/toolong/aborted/cancelled 不在此列）----\r\n          // P0-e 联动：max-tokens 截断是**确定性**结果（同 maxTokens 重试必然再截断）——\r\n          //   · 有实质文本 → 视为终态，break 出去由主生成点采纳（不进重试，省预算且语义正确）；\r\n          //   · 无文本（纯思考吃满预算） → 可能是瞬时故障，才交给策略判定是否重试。\r\n          const truncatedWithText = result && result.kind === 'maxtokens' && typeof result.text === 'string' && result.text !== '';\r\n          if (truncatedWithText) break;\r\n          const attemptFailure = result && (result.kind === 'error' || result.kind === 'maxtokens') ? (result.failure || null) : null;\r\n          if (!attemptFailure) break;\r\n          const policy = retryPolicyFor(entry.provider);\r\n          if (!isRetryableFailure(policy, attemptFailure)) break;\r\n          // always 语义官方无 maxRetries（不设限）；插件侧给安全上限防不收敛——\r\n          // 尤其 timeoutMs=0（无限制）时 budgetDeadline=null，预算不构成中断（独立复核 medium）。\r\n          const retryCap = policy.mode === 'always'\r\n            ? RETRY_ALWAYS_SAFETY_CAP\r\n            : (Number.isSafeInteger(policy.maxRetries) ? policy.maxRetries : 0);\r\n          if (attempt >= retryCap) break;\r\n          if (budgetExhausted(state)) { hlog('[enhance] retry skipped budget-exhausted code=' + attemptFailure.code); break; }\r\n          // 平铺策略对象直接传入（官方 ResolvedRetryPolicy 无 backoff 子对象）\r\n          const delayMs = computeBackoffDelayMs(policy, attempt + 1, Math.random);\r\n          // 独立复审 medium（2026-10-12）：重试**不得**混进「降级」通道——\r\n          // 「重试后成功」是瞬时故障自愈（P0-a 的目标场景），不是「上下文不完整」；\r\n          // 混入会让常见成功路径被 UI 误标「⚠ 部分上下文不可用」，削弱降级信号可信度。\r\n          // 故重试只记 hlog（可观测）与独立计数 rec.retries，绝不进 rec.degraded。\r\n          if (!Array.isArray(rec.retries)) rec.retries = [];\r\n          rec.retries.push(String(attemptFailure.code || 'unknown'));\r\n          hlog('[enhance] retry attempt=' + (attempt + 1) + '/' + retryCap + ' code=' + attemptFailure.code + ' delay=' + Math.round(delayMs) + 'ms provider=' + entry.provider + ' seq=' + seq);\r\n          setProgress(rec, STAGE_LLM, 'retry', { current: attempt + 1, total: retryCap }, attempt + 1, retryCap);\r\n          await sleepMs(delayMs);\r\n        }\r\n        if (streamThrowFailure) {\r\n          lastFailure = streamThrowFailure;\r\n          continue;\r\n        }\r\n        if (watchFired) {\n          state.watchdogDone = true;\n          hlog('[enhance] watchdog no-response in ' + WATCHDOG_TIMEOUT_MS + 'ms on ' + entry.provider + '/' + entry.model + ' seq=' + seq);\n          setProgress(rec, STAGE_LLM, 'probe', null, 1, chain.length);\n          // 连通性探测：跳过刚挂起的首条，探测剩余链（缓存优先，每条 PROBE_TIMEOUT_MS 超时）\n          const rest = chain.slice(i + 1);\n          const pick = await probeFirstReachable(rest);\n          if (!pick) {\n            // 剩余全不通 → 回头探测挂起首条：通畅（只是慢）→ 重试一次；不通 → 全不可用\n            const headOk = await probeEntry(entry);\n            if (!headOk) {\n              hlog('[enhance] chain all unavailable session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));\n              // v3.3.3（设计决策）：探测窗口已按实测放大（PROBE_TIMEOUT_MS=12s）——探测全败\n              // = 实测全不可达（慢模型不再被误杀），立即报错不进入重试轮（避免无望的二次等待）；\n              // 重试轮只覆盖生成级失败耗尽（EMPTY/STREAM_THROW/QUOTA/瞬时错误等自愈场景）。\n              state.result = { ok: false, code: 'ALL_MODELS_UNAVAILABLE', message: friendlyMessage({ code: 'ALL_MODELS_UNAVAILABLE' }) };\n              return state;\n            }\n            hlog('[enhance] watchdog retry head via ' + entry.provider + '/' + entry.model + ' seq=' + seq);\n            chain = [entry];\n            i = -1;\n            continue;\n          }\n          hlog('[enhance] watchdog restart via ' + pick.provider + '/' + pick.model + ' seq=' + seq);\n          chain = [pick].concat(chain.filter((e) => e !== pick && e !== entry));\n          i = -1;\n          continue;\n        }\n        if (result.kind === 'ok') {\n          // v2.8.0（实测修正）：publish 剥离输出首部【场景判定】回显行（确定性，不依赖模型遵从）\n          const cleaned = isPublish ? stripScenarioEcho(cleanOutput(result.text, state.text)) : cleanOutput(result.text, state.text);\n          if (cleaned === '') {\n            lastFailure = { code: 'EMPTY_RESPONSE', message: 'model returned empty text' };\n            continue;\n          }\n          hlog('[enhance] ok session=' + sessionId + ' via ' + entry.model);\n          state.result = { ok: true, text: cleaned, model: entry.model, ...(state.watchdogDone === true || i > 0 ? { fallbackUsed: true } : {}) };\n          return state;\n        }\n        if (result.kind === 'toolong') {\r\n          lastFailure = { code: 'OUTPUT_TOO_LONG', message: 'output exceeded limit' };\r\n          continue;\r\n        }\r\n        // P0-e（2026-10-12）：max-tokens 截断是**官方合法** finish（不再落 EMPTY_RESPONSE 兜底）。\r\n        // 若已收到实质文本 → 直接采纳为结果（长草稿被截断但内容可用，优于报错丢弃）；\r\n        // 无文本（纯思考吃满预算）→ 如实报 OUTPUT_TRUNCATED（文案由 friendlyMessage 给真实原因）。\r\n        if (result.kind === 'maxtokens') {\r\n          const truncated = typeof result.text === 'string' ? result.text : '';\r\n          if (truncated !== '') {\r\n            const cleanedMt = isPublish ? stripScenarioEcho(cleanOutput(truncated, state.text)) : cleanOutput(truncated, state.text);\r\n            // P0-e 修正（2026-10-12 · 独立复核 high）：截断文本**不得无条件采纳**——截断点可能落在\r\n            // 指令包装中途（模型回显「请优化以下提示词：\"\"\"…」），此时 cleanOutput 因包装未闭合剥不掉，\r\n            // 会把带包装的残片当结果覆盖用户草稿（旧行为是报 EMPTY_RESPONSE、草稿保留 ⇒ 反而更安全）。\r\n            // 采纳门槛（离线可判，不调模型）：① 剥离后非空；② 剥离后**不再含未闭合的指令包装特征**\r\n            // （三引号/「请优化以下提示词」等 wrap 痕迹）；③ 非残片（≥8 字符）。\r\n            // ⚠ 曾用「≥原文 10%」，实测会误伤「短输入 + 短而合法的截断输出」（过度收紧）——已回退为绝对值下限。\r\n            // 任一不满足 → 不采纳，按 OUTPUT_TRUNCATED 如实失败（草稿保留）。\r\n            const stillWrapped = /\"\"\"|请优化以下提示词|优化以下提示词|【用户输入】/.test(cleanedMt);\r\n            // 残片下限：极短输入（如 4 字）不应被绝对值门槛误伤——取 min(8, 原文长度) 作下限\n            const minLen = Math.min(8, Math.max(1, String(state.text || '').length));\n            const longEnough = cleanedMt.length >= minLen;\r\n            if (cleanedMt !== '' && !stillWrapped && longEnough) {\r\n              markDegraded(state, 'output-truncated');\r\n              hlog('[enhance] ok(truncated by max-tokens) session=' + sessionId + ' via ' + entry.model + ' chars=' + cleanedMt.length);\r\n              state.result = { ok: true, text: cleanedMt, model: entry.model, truncated: true, ...(state.watchdogDone === true || i > 0 ? { fallbackUsed: true } : {}) };\r\n              return state;\r\n            }\r\n            hlog('[enhance] truncated output rejected session=' + sessionId + ' wrapped=' + stillWrapped + ' longEnough=' + longEnough + ' chars=' + cleanedMt.length);\r\n          }\r\n          lastFailure = { code: 'OUTPUT_TRUNCATED', message: 'output reached the length limit and was truncated' };\r\n          continue;\r\n        }\n        if (result.kind === 'cancelled' || result.kind === 'aborted') {\n          state.result = { ok: false, code: rec.timedOut ? 'TIMEOUT' : 'ABORTED', message: friendlyMessage({ code: rec.timedOut ? 'TIMEOUT' : 'ABORTED' }) };\n          return state;\n        }\n        hlog('[enhance] fail session=' + sessionId + ' model=' + entry.model + ' code=' + (result.failure ? result.failure.code : '?'));\n        lastFailure = result.failure || { code: 'LLM_FAILED', message: 'unknown failure' };\n      }\n      // v3.3.3（链耗尽）：pass 0 且未被取消/超时 → 整链重试一次（watchdogDone=true 免看门狗）\n      if (pass === 0 && !rec.cancelled && !rec.timedOut) {\n        hlog('[enhance] chain exhausted retry pass=2 session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));\n        state.watchdogDone = true;\n        continue;\n      }\n      hlog('[enhance] chain exhausted session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));\n      state.result = { ok: false, code: lastFailure.code || 'LLM_FAILED', message: friendlyMessage(lastFailure) };\n      return state;\n      }\n    }\n\n    // v3.1.3（看门狗 + 延迟连通性预检）：连通性探测——缓存优先，pingStream 短输入探测\n    // （可达性：QUOTA/网络/auth/超时；探测 ≠ 生成成功，生成级失败仍由原回退链兜底）\n    const probeCache = new Map();\n    async function probeEntry(entry) {\n      if (!entry) return false;\n      const key = entry.provider + '/' + entry.model;\n      const now = Date.now();\n      const hit = probeCacheGet(probeCache, key, now);\n      if (hit) return hit.ok === true;\n      if (llm === undefined) return false;\n      const ref = { current: null };\n      let timedOut = false;\n      const timer = ctx.timer.timeout(() => {\n        timedOut = true;\n        if (ref.current && typeof ref.current.return === 'function') {\n          try { ref.current.return(); } catch (e) { /* 忽略 */ }\n        }\n      }, PROBE_TIMEOUT_MS);\n      let r;\n      try {\n        r = await pingStream(llm, entry, ref);\n      } finally {\n        timer();\n      }\n      const ok = !timedOut && r && r.ok === true;\n      probeCacheSet(probeCache, key, { ok, code: timedOut ? 'TIMEOUT' : (r ? r.code : 'LLM_FAILED') }, now);\n      hlog('[enhance] probe ' + entry.provider + '/' + entry.model + ' → ' + (ok ? 'ok ' + (r ? r.latencyMs : '?') + 'ms' : (timedOut ? 'timeout' : (r ? r.code : 'LLM_FAILED'))));\n      return ok;\n    }\n    async function probeFirstReachable(entries) {\n      for (const entry of entries) {\n        if (await probeEntry(entry)) return entry;\n      }\n      return null;\n    }\n\n    registerEnhanceStage('analyze', enhanceStageAnalyze, { priority: 100 });\n    registerEnhanceStage('retrieve', enhanceStageRetrieve, { priority: 100 });\n    registerEnhanceStage('assemble', enhanceStageAssemble, { priority: 100 });\n    registerEnhanceStage('llm', enhanceStageLlm, { priority: 100 });\n\n    harness.handle('enhance', async (args) => {\n      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';\n      const seq = args && typeof args.seq === 'number' ? args.seq : -1;\n      const text = args && typeof args.text === 'string' ? args.text : '';\n      const key = requestKey(sessionId, seq);\n      if (text.trim() === '' || text.startsWith('/')) {\n        return { ok: false, code: 'GUARD', message: friendlyMessage({ code: 'GUARD' }) };\n      }\n      if (llm === undefined) {\n        return { ok: false, code: 'NO_LLM', message: friendlyMessage({ code: 'NO_LLM' }) };\n      }\n\n      // v2.3（§7.3）：记录提前创建（入参校验后）——stage 从 prepare 起可被 progress RPC 轮询\n      // v3.0r（细粒度进度反馈）：rec 扩展——startedAt/detailKey/detailArgs/step/total\n      const rec = { cancelled: false, timedOut: false, iterator: null, stage: STAGE_PREPARE, startedAt: Date.now(), detailKey: '', detailArgs: null, step: 0, total: 0 };\n      pending.set(key, rec);\n\n      // M2 深化：请求状态经 Pipeline 四阶段链式传递（analyze→retrieve→assemble→llm）。\r\n      // P0-b（2026-10-12 · 超时预算错位修复；独立复核 high 修正）：主超时计时器上移到**任何阶段之前**——\r\n      // 准备阶段（analyze/retrieve/assemble，内含 5 处各 10–15s 的辅助调用）首次被真正限界，\r\n      // 不再「准备阶段不设防」；辅助调用另按剩余预算钳制（helperTimeoutMs），超预算即跳过并记降级。\r\n      // ⚠ 不劣化生成额度（复核实测过「prepare+generation 超时」的拆东墙）：总预算 = **生成额度 + 准备额度**，\r\n      //   准备最多吃掉自己的额度 ⇒ 生成阶段仍拿满原 timeoutMs。旧行为（生成计时器后挂）等价于\r\n      //   「准备不计费」；新行为是「准备有自己的上限」，两者在**所有原本能过的场景**下都仍然能过。\r\n      const state = { args, sessionId, seq, text, key, rec };\r\n      const budgetCfg = validateConfig(args && args.config);\r\n      if (args && typeof args.mode === 'string' && MODE_KEYS.includes(args.mode)) budgetCfg.mode = args.mode;\r\n      const genTimeoutMs = resolveEnhanceTimeoutMs(budgetCfg, buildTryChain(budgetCfg.fallback));\r\n      const modeRow = (SKILL_MANIFEST[budgetCfg.mode] || SKILL_MANIFEST[DEFAULT_MODE]) || {};\r\n      // 超时表由调用方传入（避免 PURE 区段内 const 的暂时性死区；见 pure.js 注释）\r\n      const prepareBudgetMs = resolvePrepareBudgetMs(modeRow.retrieve, modeRow.sources, {\r\n        relevanceMs: RELEVANCE_TIMEOUT_MS,\r\n        eventsMs: V2_SEARCH_EVENTS_TIMEOUT_MS,\r\n        workspaceMs: V2_WORKSPACE_TIMEOUT_MS,\r\n        progressMs: V2_PROGRESS_TIMEOUT_MS,\r\n        webPlanMs: WEB_PLAN_TIMEOUT_MS,\r\n        webSearchMs: WEB_SEARCH_TIMEOUT_MS,\r\n        webSearchMaxResults: WEB_SEARCH_MAX_RESULTS,\r\n      });\r\n      const totalBudgetMs = genTimeoutMs > 0 ? genTimeoutMs + prepareBudgetMs : 0;\r\n      state.budgetMs = genTimeoutMs;          // 生成额度（llm 阶段语义 / 日志沿用）\r\n      state.prepareBudgetMs = prepareBudgetMs;\r\n      state.budgetDeadline = totalBudgetMs > 0 ? Date.now() + totalBudgetMs : null;\r\n      // v3.1.7（用户需求·超时无限制）：timeoutMs<=0 不挂超时计时器（0 = 无限制，等待模型自然完成）\r\n      const timeoutDisposer = totalBudgetMs > 0 ? ctx.timer.timeout(() => {\r\n        markAndAbort(key, 'timedOut');\r\n      }, totalBudgetMs) : null;\r\n\r\n      try {\r\n        await runEnhanceStages('analyze', state);\r\n        await runEnhanceStages('retrieve', state);\r\n        await runEnhanceStages('assemble', state);\r\n        await runEnhanceStages('llm', state);\r\n        // P0-d：降级清单随结果回传（结果态 UI 可见；无降级 → 不附字段，行为零变化）\r\n        if (state.result && typeof state.result === 'object' && Array.isArray(rec.degraded) && rec.degraded.length > 0) {\r\n          state.result.degraded = rec.degraded.slice();\r\n        }\r\n        return state.result;\r\n      } catch (e) {\r\n        herr('[enhance] unexpected error session=' + sessionId + ' seq=' + seq, e);\r\n        return { ok: false, code: 'LLM_FAILED', message: friendlyMessage({ code: 'LLM_FAILED' }) };\r\n      } finally {\r\n        if (timeoutDisposer) timeoutDisposer();\r\n        pending.delete(key);\r\n      }\n    });\n\n    // ================= CHG-143：语音输入纠错（**独立语音增值步** · 非增强管线内的一步）=================\n    // 用户第三轮架构澄清（逐字）：「…是属于语言功能的增强模块，就是这个纠错**可以独立存在**的…\n    //   纠错功能打开、自动增强没打开 ⇒ 识别完成后**自动使用纠错然后就结束**；两者都开 ⇒\n    //   **先纠错然后接着增强**…**并不是集成绑定在提示词增强一起的**」。\n    // ⇒ 本 RPC 归属**语音链路**、触发点是**语音识别完成之后**，由 client 显式按两开关的组合调用；\n    //   ⚠ **不是**增强管线的 stage（增强入口 `enhance` 一步都不碰纠错 ⇒ 手动 ✨ 天然零纠错调用）。\n    // ⚠ 与增强**共用一次「增强式」模型调用式样**（chain[0] + 会话历史窗口参考），但**独立 RPC、独立预算**：\n    //   不挂进 enhance 的四阶段管道，也不消费 enhance 的预算/进度槽位（不破坏既有增强链语义）。\n    //\n    // 参考窗口 = **最近的显式会话轮次**（读法甲 · 主持侧裁定）：与既有模式族同构\n    //   （lite = 前 1 轮）；取「前 1 轮」= 最轻，合「主要为语音识别纠错」的用途。\n    //   「显式」= 只取 text 块（extractHistoryConclusions 已丢弃思考/工具调用/系统注入）。\n    const CORRECTION_WINDOW = [1, 1];              // 前 1 轮（lite 式）\n    const CORRECTION_TIMEOUT_MS = 30000;           // 独立小调用：不与 enhance 预算耦合\n    const CORRECTION_MAX_TOKENS = 4000;            // 纠错是「复述 + 局部换字」，不需要长输出\n    const CORRECTION_OUTPUT_LIMIT = 16000;         // 草稿可能很长 ⇒ 不截断过紧\n\n    async function fetchCorrectionHistory(sessionId) {\n      const sq = ctx.get('sessionQuery');\n      if (!sq || typeof sq.readSurface !== 'function') {\n        hlog('[correction] history skipped no-readSurface');\n        return '';\n      }\n      // 超时保护与既有历史腿同款（race + dispose；超时即不再等，不阻断纠错）\n      const waitAbort = startWaitAbort(ctx.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);\n      try {\n        const surface = await waitAbort.race(sq.readSurface(sessionId));\n        if (waitAbort.timedOut()) { hlog('[correction] history timeout'); return ''; }\n        const events = extractHistoryConclusions(surface && surface.events);\n        const lines = splitHistoryRounds(events, CORRECTION_WINDOW[0], CORRECTION_WINDOW[1]);\n        const text = lines.join('\\n');\n        hlog('[correction] history rounds=' + CORRECTION_WINDOW[0] + '-' + CORRECTION_WINDOW[1] + ' events=' + events.length + ' chars=' + text.length);\n        return text;\n      } catch (e) {\n        hlog('[correction] history failed', e && e.message ? e.message : e);\n        return '';\n      } finally {\n        waitAbort.dispose();\n      }\n    }\n\n    async function runCorrection(args) {\n      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';\n      const text = args && typeof args.text === 'string' ? args.text : '';\n      if (text.trim() === '') return { ok: false, code: 'GUARD', message: friendlyMessage({ code: 'GUARD' }) };\n      if (llm === undefined) return { ok: false, code: 'NO_LLM', message: friendlyMessage({ code: 'NO_LLM' }) };\n      const cfg = validateConfig(args && args.config);\n      const chain = buildTryChain(cfg.fallback);\n      if (chain.length === 0) return { ok: false, code: 'NO_MODEL', message: friendlyMessage({ code: 'NO_MODEL' }) };\n      // 参考窗口失败 ⇒ 空参考（纠错仍可依据草稿本身与判据①–④执行，降级不阻断）\n      const historyText = await fetchCorrectionHistory(sessionId);\n      const system = CORRECTION_PROMPT.replace('{history}', historyText);\n      // ⚠ 与「判定类小调用」同款：**剥离 reasoningEffort**（纠错是字词级判定，无需深度思考；\n      //   effort 思考会消耗小预算输出并放大耗时）。⚠ 但**保留 temperature=0.3**（确定性重述）。\n      let lastFailure = null;\n      for (let i = 0; i < chain.length; i++) {\n        const entry = chain[i];\n        let timedOut = false;\n        let abortIterator = null;\n        let settleTimeout = null;\n        const gate = new Promise((resolve) => { settleTimeout = resolve; });\n        const fireAbort = () => {\n          timedOut = true;\n          if (abortIterator && typeof abortIterator.return === 'function') {\n            try { abortIterator.return(); } catch (e) { /* 忽略 */ }\n          }\n          try { settleTimeout({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }\n        };\n        const timer = ctx.timer.timeout(fireAbort, CORRECTION_TIMEOUT_MS);\n        try {\n          hlog('[correction] try session=' + sessionId + ' provider=' + entry.provider + ' model=' + entry.model);\n          const stream = llm.stream({\n            provider: entry.provider,\n            model: entry.model,\n            maxTokens: CORRECTION_MAX_TOKENS,\n            temperature: 0.3,\n            system,\n            messages: [{\n              id: 'correction-' + sessionId,\n              role: 'user',\n              content: [{ type: 'text', text }],\n              source: { kind: 'user' },\n            }],\n          });\n          const iterator = stream[Symbol.asyncIterator]();\n          abortIterator = iterator;\n          const collectP = collectStream(iterator, CORRECTION_OUTPUT_LIMIT);\n          collectP.catch(() => { /* 落败方 */ });\n          const result = await Promise.race([collectP, gate]);\n          if (!timedOut && result.kind === 'ok') {\n            const out = cleanOutput(result.text, text);\n            if (typeof out === 'string' && out.trim() !== '') {\n              hlog('[correction] ok session=' + sessionId + ' chars=' + out.length + ' history=' + historyText.length);\n              return { ok: true, text: out, provider: entry.provider, model: entry.model, historyChars: historyText.length, changed: out !== text, fallbackUsed: i > 0 };\n            }\n            lastFailure = { code: 'EMPTY_RESPONSE' };\n          } else {\n            lastFailure = timedOut ? { code: 'TIMEOUT' }\n              : (result.kind === 'maxtokens' ? { code: 'OUTPUT_TRUNCATED' }\n              : (result.failure || { code: 'EMPTY_RESPONSE' }));\n          }\n        } catch (e) {\n          lastFailure = { code: e && e.code ? String(e.code) : 'STREAM_THROW', message: String(e && e.message ? e.message : e) };\n          hlog('[correction] stream failed code=' + lastFailure.code);\n        } finally {\n          try { timer(); } catch (e) { /* 忽略 */ }\n          if (abortIterator && typeof abortIterator.return === 'function') {\n            try { abortIterator.return(); } catch (e) { /* 忽略 */ }\n          }\n        }\n        const code = lastFailure ? lastFailure.code : 'UNKNOWN';\n        // 超时/截断/取消 ⇒ 确定性结果，不换下一条（省预算且语义正确）；其余（含 STREAM_THROW）走下一条\n        if (code === 'TIMEOUT' || code === 'ABORTED' || code === 'OUTPUT_TRUNCATED') break;\n      }\n      const code = lastFailure && lastFailure.code ? lastFailure.code : 'LLM_FAILED';\n      hlog('[correction] failed session=' + sessionId + ' code=' + code);\n      return { ok: false, code, message: friendlyMessage({ code }) };\n    }\n\n    harness.handle('voice/correct', async (args) => {\n      try {\n        return await runCorrection(args);\n      } catch (e) {\n        herr('[correction] unexpected error', e);\n        return { ok: false, code: 'LLM_FAILED', message: friendlyMessage({ code: 'LLM_FAILED' }) };\n      }\n    });\n\n    harness.handle('cancel', async (args) => {\n      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';\n      const seq = args && typeof args.seq === 'number' ? args.seq : -1;\n      markAndAbort(requestKey(sessionId, seq), 'cancelled');\n      return { ok: true };\n    });\n";
